create extension if not exists pgcrypto;
create sequence public.business_number;
create function public.business_ref(prefix text) returns text language sql volatile set search_path=public as $$ select prefix||'-'||to_char(now() at time zone 'Asia/Karachi','YYYY')||'-'||lpad(nextval('public.business_number')::text,6,'0') $$;
create table profiles(id uuid primary key references auth.users(id) on delete cascade,role text not null check(role='admin'),created_at timestamptz default now(),updated_at timestamptz default now());
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and role='admin') $$;
create table customers(id uuid primary key default gen_random_uuid(),name text not null,phone text unique not null check(phone ~ '^923[0-9]{9}$'),email text,referral_source text,notes text,created_at timestamptz default now(),updated_at timestamptz default now());
create table customer_addresses(id uuid primary key default gen_random_uuid(),customer_id uuid references customers not null,area text,address text,created_at timestamptz default now(),updated_at timestamptz default now());
create table products(id uuid primary key default gen_random_uuid(),name text not null,description text not null default '',category text not null,price numeric(12,2) not null check(price>=0),sale_price numeric(12,2) check(sale_price>=0 and sale_price<=price),stock integer not null default 0 check(stock>=0),preparation_hours integer not null default 24 check(preparation_hours>=0),same_day boolean default false,active boolean default true,featured boolean default false,capacity_points integer default 1 check(capacity_points>0),created_at timestamptz default now(),updated_at timestamptz default now());
create table product_images(id uuid primary key default gen_random_uuid(),product_id uuid references products on delete cascade,url text not null,created_at timestamptz default now(),updated_at timestamptz default now());
create table gallery_items(id uuid primary key default gen_random_uuid(),name text not null,category text not null,image_url text not null,starting_price numeric(12,2) check(starting_price>=0),active boolean default true,featured boolean default false,created_at timestamptz default now(),updated_at timestamptz default now());
create table custom_cake_requests(id uuid primary key default gen_random_uuid(),number text unique default business_ref('CCR'),customer_id uuid references customers not null,requirements jsonb not null,event_date date not null,status text not null default 'new_inquiry',gallery_id uuid references gallery_items,created_at timestamptz default now(),updated_at timestamptz default now());
create table custom_request_images(id uuid primary key default gen_random_uuid(),request_id uuid references custom_cake_requests not null,path text not null,created_at timestamptz default now(),updated_at timestamptz default now());
create table quotations(id uuid primary key default gen_random_uuid(),number text unique default business_ref('CCQ'),request_id uuid references custom_cake_requests not null,token_hash text unique not null,price numeric(12,2) not null check(price>=0),delivery_fee numeric(12,2) not null default 0 check(delivery_fee>=0),discount numeric(12,2) not null default 0 check(discount>=0 and discount<=price),advance numeric(12,2) not null check(advance>=0 and advance<=price-discount+delivery_fee),notes text,feasible boolean not null default true,suggested_changes text,expires_at timestamptz not null,status text not null default 'sent' check(status in ('draft','sent','accepted','rejected','expired','revised')),created_at timestamptz default now(),updated_at timestamptz default now());
create table orders(id uuid primary key default gen_random_uuid(),number text unique default business_ref('CCO'),customer_id uuid references customers not null,request_id uuid references custom_cake_requests,quotation_id uuid unique references quotations,receipt_hash text unique,type text not null check(type in ('custom','ready')),status text not null default 'awaiting_advance',event_date date not null,delivery_window text,notes text,product_subtotal numeric(12,2) not null check(product_subtotal>=0),discount numeric(12,2) not null default 0 check(discount>=0 and discount<=product_subtotal),delivery_fee numeric(12,2) not null default 0 check(delivery_fee>=0),required_advance numeric(12,2) not null default 0 check(required_advance>=0),ingredient_cost numeric(12,2) default 0 check(ingredient_cost>=0),decoration_cost numeric(12,2) default 0 check(decoration_cost>=0),packaging_cost numeric(12,2) default 0 check(packaging_cost>=0),labour_cost numeric(12,2) default 0 check(labour_cost>=0),other_direct_cost numeric(12,2) default 0 check(other_direct_cost>=0),costs_complete boolean default false,capacity_points integer not null default 2 check(capacity_points>0),completed_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table order_items(id uuid primary key default gen_random_uuid(),order_id uuid references orders not null,product_id uuid references products,name text not null,quantity integer not null check(quantity>0),unit_price numeric(12,2) not null check(unit_price>=0),created_at timestamptz default now(),updated_at timestamptz default now());
create table order_status_history(id uuid primary key default gen_random_uuid(),order_id uuid references orders not null,status text not null,note text,administrator uuid references auth.users,created_at timestamptz default now(),updated_at timestamptz default now());
create table payments(id uuid primary key default gen_random_uuid(),order_id uuid references orders not null,amount numeric(12,2) not null check(amount>0),method text not null check(method in ('cash','bank_transfer','raast','easypaisa','jazzcash','other')),type text not null default 'advance' check(type in ('advance','final','refund')),payment_date date default current_date,proof_path text,verification_status text default 'pending' check(verification_status in ('pending','verified','rejected')),verified_by uuid references auth.users,verified_at timestamptz,reference text,created_at timestamptz default now(),updated_at timestamptz default now());
create table deliveries(id uuid primary key default gen_random_uuid(),order_id uuid unique references orders not null,method text not null check(method in ('delivery','pickup')),area text,address text,driver_service text,driver_name text,driver_phone text,vehicle text,booking_reference text,pickup_time timestamptz,delivery_time timestamptz,status text default 'pending',actual_cost numeric(12,2) default 0 check(actual_cost>=0),proof_path text,notes text,created_at timestamptz default now(),updated_at timestamptz default now());
create table suppliers(id uuid primary key default gen_random_uuid(),name text not null,phone text,created_at timestamptz default now(),updated_at timestamptz default now());
create table expense_categories(id uuid primary key default gen_random_uuid(),name text unique not null,created_at timestamptz default now(),updated_at timestamptz default now());
create table expenses(id uuid primary key default gen_random_uuid(),category text not null,amount numeric(12,2) not null check(amount>0),date date not null default current_date,vendor text,receipt_path text,order_id uuid references orders,notes text,payment_method text not null default 'cash',created_at timestamptz default now(),updated_at timestamptz default now());
create table ingredients(id uuid primary key default gen_random_uuid(),name text not null,unit text not null,stock numeric(14,3) not null default 0 check(stock>=0),reorder_level numeric(14,3) default 0 check(reorder_level>=0),average_unit_cost numeric(14,4) default 0 check(average_unit_cost>=0),supplier_id uuid references suppliers,last_purchase_date date,active boolean default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table purchases(id uuid primary key default gen_random_uuid(),supplier_id uuid references suppliers,total numeric(12,2) not null check(total>0),date date default current_date,receipt_path text,notes text,created_at timestamptz default now(),updated_at timestamptz default now());
create table purchase_items(id uuid primary key default gen_random_uuid(),purchase_id uuid references purchases not null,ingredient_id uuid references ingredients not null,quantity numeric(14,3) not null check(quantity>0),unit_cost numeric(14,4) not null check(unit_cost>=0),created_at timestamptz default now(),updated_at timestamptz default now());
create table inventory_movements(id uuid primary key default gen_random_uuid(),ingredient_id uuid references ingredients not null,quantity_change numeric(14,3) not null,reason text not null,purchase_id uuid references purchases,order_id uuid references orders,administrator uuid references auth.users,created_at timestamptz default now(),updated_at timestamptz default now());
create table daily_capacity(id uuid primary key default gen_random_uuid(),date date unique not null,points integer not null check(points>0),notes text,created_at timestamptz default now(),updated_at timestamptz default now());
create table admin_notes(id uuid primary key default gen_random_uuid(),order_id uuid references orders,request_id uuid references custom_cake_requests,note text not null,administrator uuid references auth.users,created_at timestamptz default now(),updated_at timestamptz default now());
create table business_settings(id uuid primary key default gen_random_uuid(),key text unique not null,value jsonb not null,created_at timestamptz default now(),updated_at timestamptz default now());
create table notification_events(id uuid primary key default gen_random_uuid(),event text not null,order_id uuid references orders,request_id uuid references custom_cake_requests,payload jsonb default '{}',created_at timestamptz default now(),updated_at timestamptz default now());
create table submission_limits(id uuid primary key default gen_random_uuid(),key text not null,created_at timestamptz default now());
create index submission_limits_key on submission_limits(key,created_at);
create index orders_date on orders(event_date,status);
create index requests_date on custom_cake_requests(event_date,status);
create index payments_order on payments(order_id);
create index history_order on order_status_history(order_id,created_at);
create index inventory_ingredient on inventory_movements(ingredient_id,created_at);
create index quotes_request on quotations(request_id);
create function public.touch_updated() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
do $$ declare t text; begin for t in select tablename from pg_tables where schemaname='public' loop execute format('alter table public.%I enable row level security',t); execute format('create policy admin_read on public.%I for select to authenticated using (public.is_admin())',t); if t <> 'submission_limits' then execute format('create trigger touch_updated before update on public.%I for each row execute function public.touch_updated()',t); end if; end loop; end $$;
create policy public_products on products for select to anon,authenticated using(active);
create policy public_gallery on gallery_items for select to anon,authenticated using(active);
create policy public_product_images on product_images for select to anon,authenticated using(exists(select 1 from products where products.id=product_id and active));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('catalogue','catalogue',true,5242880,array['image/jpeg','image/png','image/webp']),('references','references',false,5242880,array['image/jpeg','image/png','image/webp']),('payments','payments',false,5242880,array['image/jpeg','image/png','image/webp']),('receipts','receipts',false,5242880,array['image/jpeg','image/png','image/webp']);
create policy catalogue_read on storage.objects for select using(bucket_id='catalogue');
create policy admin_storage_read on storage.objects for select to authenticated using(public.is_admin());
create function public.rate_limit(k text) returns boolean language plpgsql security definer set search_path=public as $$ begin perform pg_advisory_xact_lock(hashtextextended(k,0)); delete from submission_limits where created_at < now()-interval '1 day'; if (select count(*) from submission_limits where key=k and created_at>now()-interval '1 hour')>=15 then return false; end if; insert into submission_limits(key) values(k); return true; end $$;
create function public.customer_upsert(d jsonb) returns uuid language plpgsql set search_path=public as $$ declare cid uuid; begin insert into customers(name,phone,email) values(d->>'name',d->>'phone',nullif(d->>'email','')) on conflict(phone) do update set name=excluded.name returning id into cid; if d->>'method'='delivery' then insert into customer_addresses(customer_id,area,address) values(cid,d->>'area',d->>'address'); end if; return cid; end $$;
create function public.submit_request(d jsonb) returns jsonb language plpgsql security definer set search_path=public as $$ declare r custom_cake_requests; begin insert into custom_cake_requests(customer_id,requirements,event_date,gallery_id) values(customer_upsert(d),d,(d->>'event_date')::date,nullif(d->>'gallery_id','')::uuid) returning * into r; insert into notification_events(event,request_id) values('request_received',r.id); return jsonb_build_object('id',r.id,'number',r.number); end $$;
create function public.checkout(d jsonb,items jsonb,receipt text) returns jsonb language plpgsql security definer set search_path=public as $$ declare p products; item jsonb; subtotal numeric:=0; points integer:=0; oid uuid; num text; fee numeric:=0; begin
if jsonb_array_length(items)=0 then raise exception 'Cart is empty'; end if;
for item in select value from jsonb_array_elements(items) order by value->>'id' loop select * into p from products where id=(item->>'id')::uuid for update; if not found or not p.active or (item->>'quantity')::int<1 or p.stock<(item->>'quantity')::int then raise exception 'Product unavailable or insufficient stock'; end if; if (d->>'event_date')::date < (now() at time zone 'Asia/Karachi')::date + (case when p.same_day then 0 else ceil(p.preparation_hours/24.0)::int end) then raise exception 'Please allow product preparation time'; end if; subtotal:=subtotal+coalesce(p.sale_price,p.price)*(item->>'quantity')::int; points:=points+p.capacity_points*(item->>'quantity')::int; update products set stock=stock-(item->>'quantity')::int where id=p.id; end loop;
if d->>'method'='delivery' then select coalesce((value->>'delivery_fee')::numeric,0) into fee from business_settings where key='general'; fee:=coalesce(fee,0); end if;
insert into orders(customer_id,type,event_date,delivery_window,notes,product_subtotal,delivery_fee,receipt_hash,capacity_points) values(customer_upsert(d),'ready',(d->>'event_date')::date,d->>'delivery_window',d->>'notes',subtotal,fee,receipt,points) returning id,number into oid,num;
for item in select value from jsonb_array_elements(items) loop select * into p from products where id=(item->>'id')::uuid; insert into order_items(order_id,product_id,name,quantity,unit_price) values(oid,p.id,p.name,(item->>'quantity')::int,coalesce(p.sale_price,p.price)); end loop;
insert into deliveries(order_id,method,area,address) values(oid,d->>'method',d->>'area',d->>'address'); insert into order_status_history(order_id,status) values(oid,'awaiting_advance'); insert into notification_events(event,order_id) values('order_received',oid); return jsonb_build_object('id',oid,'number',num); end $$;
create function public.create_quote(d jsonb,hashed text) returns jsonb language plpgsql security definer set search_path=public as $$ declare q quotations; begin perform 1 from custom_cake_requests where id=(d->>'request_id')::uuid for update; if not found then raise exception 'Request not found'; end if; if exists(select 1 from quotations where request_id=(d->>'request_id')::uuid and status='accepted') then raise exception 'Accepted quotation cannot be revised'; end if; update quotations set status='revised' where request_id=(d->>'request_id')::uuid and status in ('sent','draft'); insert into quotations(request_id,token_hash,price,delivery_fee,discount,advance,notes,feasible,suggested_changes,expires_at,status) values((d->>'request_id')::uuid,hashed,(d->>'price')::numeric,(d->>'delivery_fee')::numeric,(d->>'discount')::numeric,(d->>'advance')::numeric,d->>'notes',(d->>'feasible')::boolean,d->>'suggested_changes',(d->>'expires_at')::timestamptz,d->>'status') returning * into q; update custom_cake_requests set status=case when q.status='sent' then 'quotation_sent' else 'under_review' end where id=q.request_id; insert into notification_events(event,request_id) values('quotation_'||q.status,q.request_id); return jsonb_build_object('id',q.id,'number',q.number); end $$;
create function public.decide_quote(hashed text,decision text) returns jsonb language plpgsql security definer set search_path=public as $$ declare q quotations; r custom_cake_requests; oid uuid; begin select * into q from quotations where token_hash=hashed; if not found then raise exception 'Quotation unavailable'; end if; perform 1 from custom_cake_requests where id=q.request_id for update; select * into q from quotations where token_hash=hashed for update; if q.status<>'sent' or q.expires_at<=now() then raise exception 'Quotation no longer open'; end if; if decision not in ('accepted','rejected') then raise exception 'Invalid decision'; end if; if decision='accepted' and not q.feasible then raise exception 'Please discuss the suggested changes first'; end if; update quotations set status=decision where id=q.id; if decision='accepted' then select * into r from custom_cake_requests where id=q.request_id; insert into orders(customer_id,request_id,quotation_id,type,event_date,delivery_window,product_subtotal,discount,delivery_fee,required_advance) values(r.customer_id,r.id,q.id,'custom',r.event_date,r.requirements->>'delivery_window',q.price,q.discount,q.delivery_fee,q.advance) returning id into oid; insert into deliveries(order_id,method,area,address) values(oid,r.requirements->>'method',r.requirements->>'area',r.requirements->>'address'); insert into order_status_history(order_id,status) values(oid,'awaiting_advance'); update custom_cake_requests set status='awaiting_advance' where id=r.id; end if; return jsonb_build_object('status',decision,'order_id',oid); end $$;
create function public.transition_order(oid uuid,next_status text,actor uuid,audit_note text default null) returns void language plpgsql security definer set search_path=public as $$ declare o orders; paid numeric; allowed boolean:=false; begin select * into o from orders where id=oid for update; if not found then raise exception 'Order not found'; end if; if next_status=o.status then return; end if;
allowed:=case o.status when 'awaiting_advance' then next_status in ('payment_verification','confirmed','cancelled') when 'payment_verification' then next_status in ('confirmed','awaiting_advance','cancelled') when 'confirmed' then next_status in ('ingredients_required','in_preparation','cancelled') when 'ingredients_required' then next_status in ('in_preparation','cancelled') when 'in_preparation' then next_status in ('ready','cancelled') when 'ready' then next_status in ('rider_assigned','delivered','cancelled') when 'rider_assigned' then next_status in ('out_for_delivery','cancelled') when 'out_for_delivery' then next_status='delivered' when 'delivered' then next_status in ('completed','refunded') when 'completed' then next_status='refunded' else false end;
if not allowed then raise exception 'Invalid status transition'; end if;
if next_status='confirmed' then select coalesce(sum(case when type='refund' then -amount else amount end),0) into paid from payments where order_id=oid and verification_status='verified'; if paid<o.required_advance and length(trim(coalesce(audit_note,'')))<10 then raise exception 'Verified advance required, or an explicit override note of at least 10 characters'; end if; end if;
if next_status='cancelled' and o.type='ready' then update products p set stock=p.stock+i.quantity from (select product_id,sum(quantity)::int quantity from order_items where order_id=oid group by product_id) i where p.id=i.product_id; end if;
update orders set status=next_status,completed_at=case when next_status='completed' then now() else completed_at end where id=oid; update custom_cake_requests set status=next_status where id=o.request_id; insert into order_status_history(order_id,status,note,administrator) values(oid,next_status,audit_note,actor); insert into notification_events(event,order_id) values(case next_status when 'confirmed' then 'order_confirmed' when 'ready' then 'cake_ready' when 'out_for_delivery' then 'rider_dispatched' when 'delivered' then 'order_delivered' when 'completed' then 'review_request' else 'status_changed' end,oid); end $$;
create function public.verify_payment(pid uuid,actor uuid) returns void language plpgsql security definer set search_path=public as $$ declare p payments; begin select * into p from payments where id=pid for update; if not found or p.verification_status<>'pending' then raise exception 'Payment is not pending'; end if; update payments set verification_status='verified',verified_by=actor,verified_at=now() where id=pid; insert into notification_events(event,order_id) values('payment_verified',p.order_id); end $$;
create function public.record_purchase(d jsonb,actor uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare i ingredients; pid uuid; qty numeric:=(d->>'quantity')::numeric; cost numeric:=(d->>'unit_cost')::numeric; begin if qty<=0 or cost<=0 then raise exception 'Positive quantity and cost required'; end if; select * into i from ingredients where id=(d->>'ingredient_id')::uuid for update; if not found then raise exception 'Ingredient not found'; end if; insert into purchases(supplier_id,total,date,notes,receipt_path) values(nullif(d->>'supplier_id','')::uuid,qty*cost,(d->>'date')::date,d->>'notes',d->>'receipt_path') returning id into pid; insert into purchase_items(purchase_id,ingredient_id,quantity,unit_cost) values(pid,i.id,qty,cost); update ingredients set average_unit_cost=(stock*average_unit_cost+qty*cost)/(stock+qty),stock=stock+qty,last_purchase_date=(d->>'date')::date where id=i.id; insert into inventory_movements(ingredient_id,quantity_change,reason,purchase_id,administrator) values(i.id,qty,'purchase',pid,actor); return pid; end $$;
create function public.adjust_inventory(d jsonb,actor uuid) returns void language plpgsql security definer set search_path=public as $$ begin update ingredients set stock=stock+(d->>'quantity_change')::numeric where id=(d->>'ingredient_id')::uuid; if not found then raise exception 'Ingredient not found'; end if; insert into inventory_movements(ingredient_id,quantity_change,reason,order_id,administrator) values((d->>'ingredient_id')::uuid,(d->>'quantity_change')::numeric,d->>'reason',nullif(d->>'order_id','')::uuid,actor); end $$;
-- All privileged functions are callable only by controlled server-side service code.
do $$ declare f record; begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('rate_limit','customer_upsert','submit_request','checkout','create_quote','decide_quote','transition_order','verify_payment','record_purchase','adjust_inventory','business_ref') loop execute format('revoke all on function %s from public,anon,authenticated',f.signature); execute format('grant execute on function %s to service_role',f.signature); end loop; end $$;
